meta=p.with_name('inputs.json');spec=json.loads(meta.read_text());spec['original_library_closure_sha256']=spec['source_sha256'];spec['source_sha256']=sha(fixed);spec['member_overrides']={'pm.maxLength':{'original_text':'maxLength = 3;','derived_text':'maxLength = 17.05;','reason':'Cover original 20 Hz frequency endpoint without delay-capacity clipping','derived_sha256':sha(b'maxLength = 17.05;')}};spec['status']='DERIVATIVE_CLOSURE_WITH_EXPLICIT_OVERRIDE';meta.write_text(json.dumps(spec,indent=2)+'\n')
